import{_ as i,c as a,o as t,aB as e}from"./chunks/framework.DeK-WOGe.js";const n="/posts/cs-message-list/01.png",l="/posts/cs-message-list/02.png",p="/posts/cs-message-list/03.png",h="/posts/cs-message-list/04.png",F=JSON.parse('{"title":"在线客服后台：消息列表渲染机制","description":"聊天消息列表的虚拟滚动、高度测量，以及历史位置跳转。","frontmatter":{"title":"在线客服后台：消息列表渲染机制","date":"2026-06-05T00:00:00.000Z","description":"聊天消息列表的虚拟滚动、高度测量，以及历史位置跳转。","outline":"deep"},"headers":[],"relativePath":"front/cs-message-list.md","filePath":"front/cs-message-list.md"}'),d={name:"front/cs-message-list.md"};function r(k,s,o,c,g,E){return t(),a("div",null,[...s[0]||(s[0]=[e('<h1 id="在线客服后台-消息列表渲染机制" tabindex="-1">在线客服后台：消息列表渲染机制 <a class="header-anchor" href="#在线客服后台-消息列表渲染机制" aria-label="Permalink to &quot;在线客服后台：消息列表渲染机制&quot;">​</a></h1><blockquote><p>写于 2026-06-05</p></blockquote><p>聊天消息列表要同时处理三件事：消息高度不固定（图片、富文本、不同屏宽）、历史消息可能很长、滚动还得跟手。做法是只渲染视口附近的节点，再用一段连续的历史块支撑「跳到某条旧消息」。</p><h2 id="三层分工" tabindex="-1">三层分工 <a class="header-anchor" href="#三层分工" aria-label="Permalink to &quot;三层分工&quot;">​</a></h2><p><img src="'+n+`" alt="" data-fancybox="gallery"></p><ul><li><strong>数据层</strong>维护已加载的消息块，以及这些块在完整时间线上的顺序。往下只输出当前允许渲染的连续片段。</li><li><strong>测量层</strong>用 ResizeObserver 记下每条已渲染消息的真实高度，键是消息 id，值是像素。还没渲染过的条目先按 60px 估算，滚进窗口后再换成实测值。卸载 DOM 时不删这张表，同一条消息再次进入视口直接查表。</li><li><strong>窗口层</strong>用 <code>scrollTop</code> 和高度表算出 <code>startIndex</code> / <code>endIndex</code>，再用上下两块 padding 把滚动条撑成「全部都在」的长度。</li></ul><p>测量回调一次可能带进多条高度变化。如果用 <code>reactive</code> 的 Map，每次 <code>set</code> 都会让依赖它的计算重跑一遍。这里用 <code>ref</code> 包 Map：先在旧实例上改完，最后 <code>sizeMap.value = new Map(sizeMap.value)</code>，一批变化只触发一次。</p><h2 id="窗口怎么裁" tabindex="-1">窗口怎么裁 <a class="header-anchor" href="#窗口怎么裁" aria-label="Permalink to &quot;窗口怎么裁&quot;">​</a></h2><p>从上往下累加高度，真实值优先，没有就用 60px。第一个累计高度超过 <code>scrollTop - 300</code> 的条目作为起点。300px 来自 <code>overscan = 5</code>，也就是视口外预先多挂 5 条，快速上滚时少出空白。终点用同样的办法探到 <code>scrollTop + containerHeight + 300</code>。</p><p>贴底时不按估算裁尾部，直接渲染到最后一条，底部 padding 归零。新消息到来时，如果还靠默认高度猜窗口，最新的气泡可能落在窗口外面。贴底的判定是容器底部剩余距离小于 200px：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> isNearBottom</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> computed</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> el</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> containerRef.value;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">el) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> el.scrollHeight </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> scrollTop.value </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> el.clientHeight </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 200</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>窗口范围必须在渲染前算出来。IntersectionObserver 只能看已经挂上的节点，所以它只负责「加载更多」的触发，不参与起止索引。</p><h2 id="dom" tabindex="-1">DOM <a class="header-anchor" href="#dom" aria-label="Permalink to &quot;DOM&quot;">​</a></h2><p><img src="`+l+`" alt="" data-fancybox="gallery"></p><p>消息仍在正常文档流里。上下两个空 div 垫出被裁掉的高度。高度表逐渐变准之后，padding 从估算收敛到实测，用户能感觉到的主要是滚动条长短的细微变化。</p><p>输入框被拖高时，容器高度变化会让窗口重算一次，浏览器也可能顺手改 <code>scrollTop</code>，再触发一轮滚动计算。多走一轮，结果是对的。</p><h2 id="跳到某一条" tabindex="-1">跳到某一条 <a class="header-anchor" href="#跳到某一条" aria-label="Permalink to &quot;跳到某一条&quot;">​</a></h2><p>定位分两步。</p><p>先用高度表把目标大致滚进渲染窗口，未测量的仍按 60px 加。目标节点挂上之后，不再信这张表，改读它和容器的 <code>getBoundingClientRect()</code>。上面的图片如果后加载、把目标顶下去，就按差值把 <code>scrollTop</code> 修回来，让目标停在视口中部：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> targetRect</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> targetEl.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getBoundingClientRect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> containerRect</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> el.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getBoundingClientRect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> targetMid</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> targetRect.top </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> containerRect.top </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> targetRect.height </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">el.scrollTop </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> targetMid </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> el.clientHeight </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>用户一旦用滚轮或触摸接管，修正马上停。另外设 30 秒上限，避免异常时一直改滚动位置。目标自身测完就停是不够的：上方大图可能更晚才撑开，停早了，偏差会留在页面上。</p><h2 id="历史里的洞" tabindex="-1">历史里的洞 <a class="header-anchor" href="#历史里的洞" aria-label="Permalink to &quot;历史里的洞&quot;">​</a></h2><p>一条历史会话是一个块。完整顺序在元信息列表里，已加载的块只是其中一段。相邻已加载块在完整顺序里不连续，中间就是洞。例如顺序是 A、B、C、D，手里只有 A 和 C，A 与 C 之间的 B 还没加载。</p><p><img src="`+p+'" alt="" data-fancybox="gallery"></p><p>渲染只取从头开始的连续段。遇到第一个洞，洞前面的块可见，洞后面的全部不可见。这样列表里不会出现一块空白。</p><p>跳转到某条旧消息时，按完整顺序找到目标块，补上它和前后各一块，按原顺序合并进已有数据，已在内存里的不重复请求。合并后再从头部收一次连续段，算出目标在可见列表中的下标，交给上面的滚动定位。</p><p><img src="'+h+'" alt="" data-fancybox="gallery"></p><p>这次加载如果中途换了会话，用一个递增的版本号丢掉过期结果，避免旧请求写回当前列表。</p><p>新消息到达时先插进当前块，让气泡马上出现；随后用一次全量结果覆盖这一块，纠正顺序。正在看历史、当前块不在列表里时，只提示有新消息，不改正在看的那段。</p><h2 id="为什么用-padding-不用-translatey" tabindex="-1">为什么用 padding，不用 translateY <a class="header-anchor" href="#为什么用-padding-不用-translatey" aria-label="Permalink to &quot;为什么用 padding，不用 translateY&quot;">​</a></h2><p>成熟的虚拟列表多半用 <code>translateY</code> 加绝对定位。聊天列表要经常往上接历史，这种做法有两个麻烦：绝对定位的节点不进文档流，浏览器的 <code>overflow-anchor</code> 选不中它们，往前插入后视口会漂；每插一批，后面所有项的偏移都要重算。</p><table tabindex="0"><thead><tr><th>方案</th><th>padding</th><th>translateY</th></tr></thead><tbody><tr><td>文档流</td><td>消息留在正常流里</td><td>绝对定位，脱离文档流</td></tr><tr><td>向上插入</td><td>只改顶部占位高度</td><td>重算后续每一项的偏移</td></tr><tr><td>overflow-anchor</td><td>可以选中消息节点</td><td>绝对定位节点不会被选为锚点</td></tr></tbody></table><p>高度差的主动修正是主路径。图片懒加载、字体晚到这类事先量不到的变化，交给 <code>overflow-anchor</code> 兜底。页头、分隔线和页脚显式设 <code>overflow-anchor: none</code>，避免它们被当成锚点。</p>',33)])])}const u=i(d,[["render",r]]);export{F as __pageData,u as default};
